// Normalize incoming events from multiple sources into a common schema.
// Supports: HF scanner webhooks, IAM scanner output, MCP gateway alerts,
// CloudTrail GuardDuty findings, and generic SARIF.

const raw = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};

// Detect source by presence of known fields
let source = 'unknown';
let severity = 'medium';
let title = '';
let details = {};
let dedup_key = '';

if (raw.findings && raw.scan_target) {
  // HF Model Provenance Scanner output
  source = 'hf-provenance-scanner';
  severity = raw.risk?.level?.toLowerCase() || 'medium';
  title = `Model supply chain: ${raw.findings.length} findings on ${raw.scan_target}`;
  details = { repo: raw.scan_target, findings: raw.findings, risk: raw.risk };
  dedup_key = `hf-${raw.scan_target}-${raw.risk?.score}`;

} else if (raw.rule_id && raw.rule_id.startsWith('AIG')) {
  // IAM Scanner finding
  source = 'aws-agent-identity-guard';
  severity = raw.severity || 'high';
  title = `IAM: ${raw.rule_id} on ${raw.resource_name}`;
  details = raw;
  dedup_key = `iam-${raw.rule_id}-${raw.resource_name}`;

} else if (raw.account_id && raw.findings) {
  // IAM Scanner full report
  source = 'aws-agent-identity-guard';
  const crit = raw.findings.filter(f => f.severity === 'critical').length;
  severity = crit > 0 ? 'critical' : 'high';
  title = `IAM Posture: ${raw.findings.length} findings in account ${raw.account_id}`;
  details = { account: raw.account_id, summary: raw.summary, top: raw.findings.slice(0, 5) };
  dedup_key = `iam-account-${raw.account_id}-${raw.findings.length}`;

} else if (raw.call_id && raw.tool_name) {
  // MCP Gateway alert
  source = 'mcp-security-gateway';
  severity = raw.blocked ? 'high' : 'medium';
  title = `MCP: ${raw.detection_type} on tool ${raw.tool_name}`;
  details = raw;
  dedup_key = `mcp-${raw.tool_name}-${raw.detection_type}`;

} else if (raw.detail?.type && raw.source === 'aws.guardduty') {
  // GuardDuty finding via EventBridge
  source = 'guardduty';
  severity = raw.detail.severity >= 7 ? 'critical' : raw.detail.severity >= 4 ? 'high' : 'medium';
  title = `GuardDuty: ${raw.detail.type}`;
  details = { finding_id: raw.detail.id, type: raw.detail.type, resource: raw.detail.resource };
  dedup_key = `gd-${raw.detail.id}`;

} else if (raw.runs && raw.$schema?.includes('sarif')) {
  // Generic SARIF input
  source = 'sarif';
  const results = raw.runs?.[0]?.results || [];
  const errors = results.filter(r => r.level === 'error');
  severity = errors.length > 0 ? 'high' : 'medium';
  title = `SARIF: ${results.length} results from ${raw.runs[0]?.tool?.driver?.name}`;
  details = { tool: raw.runs[0]?.tool?.driver?.name, results_count: results.length };
  dedup_key = `sarif-${raw.runs[0]?.tool?.driver?.name}-${results.length}`;

} else {
  title = `Unknown event from ${headers['user-agent'] || 'unknown'}`;
  details = raw;
  dedup_key = `unknown-${Date.now()}`;
}

return [{
  json: {
    event_id: `evt_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    source,
    severity,
    title,
    details,
    dedup_key,
    received_at: new Date().toISOString(),
    raw_size_bytes: JSON.stringify(raw).length
  }
}];

// Enrich the event with threat intelligence context.
// In production this calls VirusTotal, AbuseIPDB, or internal TI feeds.
// Here we add MITRE ATT&CK mapping based on the event source.

const event = $('Normalize Event').first().json;
let attack_techniques = [];
let attack_tactics = [];
let priority_score = 0;

switch (event.source) {
  case 'hf-provenance-scanner':
    attack_techniques = ['T1195.002', 'T1059.006', 'T1204.002'];
    attack_tactics = ['TA0001', 'TA0002', 'TA0005'];
    priority_score = event.severity === 'critical' ? 95 : event.severity === 'high' ? 75 : 40;
    break;
  case 'aws-agent-identity-guard':
    attack_techniques = ['T1078.004', 'T1098', 'T1548'];
    attack_tactics = ['TA0004', 'TA0003', 'TA0005'];
    priority_score = event.severity === 'critical' ? 90 : event.severity === 'high' ? 70 : 35;
    break;
  case 'mcp-security-gateway':
    attack_techniques = ['T1059', 'T1041', 'T1567'];
    attack_tactics = ['TA0002', 'TA0010', 'TA0010'];
    priority_score = event.severity === 'critical' ? 85 : event.severity === 'high' ? 65 : 30;
    break;
  case 'guardduty':
    attack_techniques = ['T1190', 'T1110'];
    attack_tactics = ['TA0001', 'TA0006'];
    priority_score = event.severity === 'critical' ? 95 : event.severity === 'high' ? 80 : 50;
    break;
  default:
    priority_score = 25;
}

return [{
  json: {
    ...event,
    enrichment: {
      mitre_attack: { techniques: attack_techniques, tactics: attack_tactics },
      priority_score,
      sla_minutes: priority_score >= 80 ? 15 : priority_score >= 60 ? 60 : 480,
      auto_remediate: priority_score >= 85 && event.source === 'aws-agent-identity-guard',
      requires_human: priority_score >= 80
    }
  }
}];

