// Auto-remediation: attach a deny-all permission boundary to the offending role.
// This is non-destructive (doesn't delete the role) but immediately contains
// the blast radius while humans investigate.

const event = $input.first().json;
const roleName = event.details?.resource_name || event.details?.top?.[0]?.resource_name;

if (!roleName) {
  return [{ json: { action: 'skip', reason: 'no role name in event details' } }];
}

// The actual AWS CLI command to attach a deny-all boundary.
// In production, this would use an IAM role with only iam:PutRolePermissionsBoundary.
const command = [
  'aws', 'iam', 'put-role-permissions-boundary',
  '--role-name', roleName,
  '--permissions-boundary', `arn:aws:iam::${event.details?.account || 'ACCOUNT_ID'}:policy/SecurityContainment-DenyAll`
].join(' ');

return [{
  json: {
    action: 'contain',
    command,
    role: roleName,
    note: 'Attached deny-all permission boundary. Role still exists but cannot perform any action until boundary is removed by security team.',
    event_id: event.event_id
  }
}];

